  "/lib/components/ui/form/FormField.svelte": "<script lang=\"ts\">\n\timport { type InputType } from './form-shared';\n\timport { cn } from '../utils/cn';\n\n\tinterface Props {\n\t\tlabel: string;\n\t\tid: string;\n\t\ttype?: InputType;\n\t\tvalue?: string | undefined;\n\t\tplaceholder?: string;\n\t\trequired?: boolean;\n\t\tdisabled?: boolean;\n\t\thint?: string;\n\t\terror?: string;\n\t\tclass?: string;\n\t\tname?: string;\n\t\tonblur?: () => void;\n\t\toninput?: (event: Event) => void;\n\t}\n\n\tlet {\n\t\tlabel,\n\t\tid,\n\t\ttype = 'text',\n\t\tvalue = $bindable('' as string | undefined),\n\t\tplaceholder = '',\n\t\trequired = false,\n\t\tdisabled = false,\n\t\thint,\n\t\terror = '',\n\t\tclass: className = '',\n\t\tname,\n\t\tonblur,\n\t\toninput\n\t}: Props = $props();\n</script>\n\n<div class={className}>\n\t<label for={id} class=\"label\">\n\t\t<span class=\"label-text flex justify-between items-center\" style=\"gap: var(--gap-lg)\">\n\t\t\t<span>\n\t\t\t\t{label}\n\t\t\t\t{#if hint}\n\t\t\t\t\t<span class=\"opacity-70\">{hint}</span>\n\t\t\t\t{/if}\n\t\t\t</span>\n\t\t\t{#if error}\n\t\t\t\t<span class=\"text-error-500 shrink-0\" style=\"font-size: var(--text-caption); font-weight: var(--weight-label)\">{error}</span>\n\t\t\t{/if}\n\t\t</span>\n\t\t<input\n\t\t\t{id}\n\t\t\t{type}\n\t\t\t{name}\n\t\t\tbind:value\n\t\t\t{placeholder}\n\t\t\t{required}\n\t\t\t{disabled}\n\t\t\t{onblur}\n\t\t\t{oninput}\n\t\t\tclass=\"input {error ? 'border-error-500' : ''}\"\n\t\t/>\n\t</label>\n</div>\n",
  "/lib/components/ui/form/TextArea.svelte": "<script lang=\"ts\">\n\timport { cn } from '../utils/cn';\n\n\tinterface Props {\n\t\tid?: string;\n\t\tname?: string;\n\t\tvalue?: string;\n\t\tplaceholder?: string;\n\t\trequired?: boolean;\n\t\tdisabled?: boolean;\n\t\terror?: boolean;\n\t\trows?: number;\n\t\tmaxlength?: number;\n\t\tclass?: string;\n\t}\n\n\tlet {\n\t\tid,\n\t\tname,\n\t\tvalue = $bindable(''),\n\t\tplaceholder = '',\n\t\trequired = false,\n\t\tdisabled = false,\n\t\terror = false,\n\t\trows = 3,\n\t\tmaxlength,\n\t\tclass: className = ''\n\t}: Props = $props();\n\n\tconst normalClass = 'textarea';\n\n\tconst errorClass =\n\t\t'textarea border-error-500 text-error-900-100 placeholder:text-error-400-500';\n\n\tconst textareaClass = $derived(cn(error ? errorClass : normalClass, className));\n</script>\n\n<textarea\n\t{id}\n\t{name}\n\tbind:value\n\t{placeholder}\n\t{required}\n\t{disabled}\n\t{rows}\n\t{maxlength}\n\tclass={textareaClass}\n></textarea>\n",
